  "contracts": {
    "def-hh-universal-coxeter-hecke-parameters-and-presentation": {
      "citations": [
        {
          "fact": "F1",
          "source": "lem-hh-free-associative-ring-and-relations-descent",
          "source_section": "Statement",
          "quote": "There is a unital associative $R$-algebra $R\\langle S\\rangle$, the **free associative $R$-algebra on $S$**, whose underlying $R$-module is free on the set of finite words in $S$ (including the empty word), with product given on words by concatenation and extended $R$-bilinearly.",
          "uses": [
            "1.2",
            "1.5",
            "1.6"
          ]
        },
        {
          "fact": "F2",
          "source": "lem-hh-finite-polynomial-and-localization-constructions",
          "source_section": "Statement",
          "quote": "**Laurent polynomial ring.** The set $\\Lambda_{R,n}$ of finitely supported functions $\\mathbb Z^n\\to R$ with coefficientwise addition and convolution $(ab)_\\gamma=\\sum_{\\alpha+\\beta=\\gamma}a_\\alpha b_\\beta$ is a commutative $R$-algebra, free as an $R$-module on the monomials $x^\\alpha$ ($\\alpha\\in\\mathbb Z^n$); each $x_i$ is a unit. For every commutative $R$-algebra $A$ and units $u_1,\\dots,u_n\\in A$ there is a unique $R$-algebra homomorphism $\\Lambda_{R,n}\\to A$ with $x_i\\mapsto u_i$.",
          "uses": [
            "1.2",
            "1.5",
            "1.6"
          ]
        },
        {
          "fact": "F3",
          "source": "def-algebra-over-a-commutative-ring",
          "source_section": "Definition",
          "quote": "An **$R$-algebra** is a unital ring $A$ together with a unital ring homomorphism $$\\eta_A:R\\longrightarrow A$$ ([[def-ring-homomorphism]]) whose image is central: $\\eta_A(r)a=a\\eta_A(r)$ for every $r\\in R$ and $a\\in A$. The induced scalar action is $ra:=\\eta_A(r)a$, making $A$ an $R$-module and multiplication $A\\times A\\to A$ bilinear. An **$R$-algebra homomorphism** $f:A\\to B$ is a unital ring homomorphism satisfying $f\\circ\\eta_A=\\eta_B$.",
          "uses": [
            "1.2",
            "1.5"
          ]
        },
        {
          "fact": "F4",
          "source": "def-hh-coxeter-matrix-word-group-and-length",
          "source_section": "Definition",
          "quote": "**Universal property.** For every group $G$ and every map $f:S\\to G$ with $f(s)^2=1$ for all $s\\in S$ and $(f(s)f(t))^{m(s,t)}=1$ in $G$ for all $s\\ne t$ with $m(s,t)<\\infty$, there is a unique group homomorphism $\\varphi:W\\to G$ with $\\varphi(s)=f(s)$ for all $s\\in S$",
          "uses": [
            "1.3",
            "1.4"
          ]
        },
        {
          "fact": "F5",
          "source": "def-conjugacy-class-and-centralizer",
          "source_section": "Definition",
          "quote": "The **conjugacy class** of $x$ is $$\\operatorname{Cl}_G(x):=\\{gxg^{-1}:g\\in G\\}.$$",
          "uses": [
            "1.3",
            "2.1"
          ]
        },
        {
          "fact": "F6",
          "source": "def-group-homomorphism",
          "source_section": "Definition",
          "quote": "a group homomorphism automatically satisfies $f(e) = e'$ and $f(x^{-1}) = f(x)^{-1}$",
          "uses": [
            "1.4"
          ]
        }
      ],
      "derivations": [
        {
          "id": "d-1.1",
          "claim": "1.1 The relation is reflexive (the one-term chain with $k=0$), symmetric (a chain $s=s_0,\\dots,s_k=t$ with all $m(s_i,s_{i+1})$ odd reverses to a chain from $t$ to $s$, because $m$ is symmetric) and transitive (two chains are concatenated at their common endpoint).",
          "step": "1.1",
          "inputs": [
            "1.1"
          ]
        },
        {
          "id": "d-1.2",
          "claim": "1.2 Since $R$ is a commutative ring in which each $v_i$ is a unit ([F2]), $F$ is a unital associative $R$-algebra with central $R$-image and $I$ is the two-sided ideal generated by the displayed finitely many relations ([F1], [F3]).",
          "step": "1.2",
          "inputs": [
            "1.2",
            "F1",
            "F2",
            "F3"
          ]
        },
        {
          "id": "d-1.3",
          "claim": "1.3 Suppose $s\\ne t$ and $m:=m(s,t)$ is finite odd, say $m=2k+1$ with $k\\ge1$.",
          "step": "1.3",
          "inputs": [
            "1.3",
            "F4",
            "F5"
          ]
        },
        {
          "id": "d-1.4",
          "claim": "1.4 Fix a class $C$ of $\\sim$ and define $\\varphi_C:S\\to\\{\\pm1\\}$ by $\\varphi_C(u)=-1$ for $u\\in C$ and $\\varphi_C(u)=1$ for $u\\in S\\setminus C$.",
          "step": "1.4",
          "inputs": [
            "1.4",
            "F4",
            "F6"
          ]
        },
        {
          "id": "d-1.5",
          "claim": "1.5 By the universal property of the Laurent ring ([F2]) the assignment $v_i\\mapsto u_i$ extends uniquely to a ring homomorphism $R\\to A$ for every commutative ring $A$ and units $u_1,\\dots,u_c\\in A^\\times$;",
          "step": "1.5",
          "inputs": [
            "1.2",
            "1.5",
            "F1",
            "F2",
            "F3"
          ]
        },
        {
          "id": "d-1.6",
          "claim": "1.6 Expanding in the free algebra, using that the coefficients $v_s$ and $v_s^{-1}$ are central ([F1]), gives $(T_s-v_s)(T_s+v_s^{-1})=T_s^2-(v_s-v_s^{-1})T_s-1$, and the reverse product $(T_s+v_s^{-1})(T_s-v_s)$ is the same element;",
          "step": "1.6",
          "inputs": [
            "1.6",
